head.script:
window.dataLayer = window.dataLayer || [];
function gtag() { dataLayer.push(arguments); }
gtag("js", new Date());
gtag("config", "G-0VL3ZSBXDH");

// Initialize Dark Shadow Theme
document.documentElement.setAttribute('data-bg-theme', localStorage.getItem('bgTheme') || 'red');

// Snow effect
function createSnowflakes() {
  const root = document.getElementById('root');
  if (!root) return;
  for (let i = 0; i < 10; i++) {
    const snowflake = document.createElement('div');
    snowflake.className = 'snowflake';
    snowflake.style.left = Math.random() * window.innerWidth + 'px';
    snowflake.style.animationDuration = (10 + Math.random() * 5) + 's';
    snowflake.style.animationDelay = Math.random() * 2 + 's';
    root.appendChild(snowflake);
  }
}

// Theme color changer for settings
window.changeThemeColor = function(color) {
  document.documentElement.setAttribute('data-bg-theme', color);
  localStorage.setItem('bgTheme', color);
};

// Create snowflakes when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', createSnowflakes);
} else {
  createSnowflakes();
}
